<script setup lang="ts">
import {computed,nextTick,onUnmounted,ref,watch} from 'vue'
import UiIcon from './UiIcon.vue'
import { vDialogDismiss } from './dialogDismiss'
import {useSession,type Config} from './api'
const props=defineProps<{config:Config;ask:(title:string,lines:string[])=>Promise<string>}>()
const emit=defineEmits<{refresh:[];notice:[message:string]}>()
const session=useSession(),api=session.request
interface FileResult {path:string;text:string;revision:string;readOnly:boolean;kind:string;cancelled?:boolean}
const path=ref(''),loaded=ref(''),text=ref(''),baseline=ref(''),revision=ref(''),readOnly=ref(false),busy=ref(false),error=ref(''),history=ref(false),query=ref(''),cursor=ref(-1),editor=ref<HTMLTextAreaElement>(),knownHost=ref(''),observation=ref('')
interface Directory {path:string;parent:string|null;entries:{name:string;path:string;directory:boolean}[];truncated:boolean}
const browser=ref<HTMLDialogElement>(),directory=ref<Directory|null>(null),directoryPath=ref(''),browserError=ref('')
let browseSequence=0
async function browse(p=''){const sequence=++browseSequence;browserError.value='';try{const result=await api<Directory>('files.browse',{path:p});if(sequence!==browseSequence)return;directory.value=result;directoryPath.value=result.path}catch(e){if(sequence===browseSequence)browserError.value=e instanceof Error?e.message:String(e)}}
async function chooseEntry(entry:Directory['entries'][number]){if(entry.directory){await browse(entry.path);return}if(!await protect())return;browser.value?.close();await open(entry.path,true)}
const isDirty=computed(()=>text.value!==baseline.value)
defineExpose({isDirty})
const matches=computed(()=>{const q=query.value.toLocaleLowerCase();if(!q)return [];const source=text.value.toLocaleLowerCase(),found:number[]=[];let i=0;while((i=source.indexOf(q,i))!==-1){found.push(i);i+=Math.max(1,q.length)}return found})
watch(query,()=>{cursor.value=-1})
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false;emit('refresh')}}
async function protect(){return !isDirty.value||await props.ask('放弃当前文件的修改？',['未保存的内容将被放弃。'])==='continue'}
function accept(file:FileResult){loaded.value=file.path;path.value=file.path;text.value=file.text;baseline.value=file.text;revision.value=file.revision;readOnly.value=file.readOnly;query.value='';cursor.value=-1;observation.value='';history.value=false}
async function open(p=path.value,protectedAlready=false){if(!p.trim()||!protectedAlready&&!await protect())return;await run(async()=>accept(await api<FileResult>('files.open',{path:p.trim()})))}
async function choose(){if(session.environment!=='windows'){await browse(loaded.value?loaded.value.slice(0,loaded.value.lastIndexOf('/')):'');browser.value?.showModal();return}if(!await protect())return;await run(async()=>{const f=await api<FileResult>('files.choose');if(!f.cancelled)accept(f)})}
async function forget(p:string){await run(async()=>{await api('files.forget',{path:p});emit('notice','已移除文件历史')})}
async function save(){await run(async()=>{const r=await api<{revision:string;backup:string}>('files.write',{path:loaded.value,text:text.value,revision:revision.value});revision.value=r.revision;baseline.value=text.value;emit('notice',`已保存；备份 ${r.backup}`)})}
async function locate(delta:number){if(!matches.value.length)return;cursor.value=(cursor.value+delta+matches.value.length)%matches.value.length;await nextTick();const start=matches.value[cursor.value]!;editor.value?.focus();editor.value?.setSelectionRange(start,start+query.value.length);if(editor.value){const line=text.value.slice(0,start).split('\n').length-1;const lineHeight=parseFloat(getComputedStyle(editor.value).lineHeight)||21;editor.value.scrollTop=Math.max(0,line*lineHeight-editor.value.clientHeight/2)}}
async function known(action:string){if(action==='knownHosts.remove'){if(!await protect())return;if(await props.ask('删除当前文件中的主机指纹？',[`${knownHost.value} · ${loaded.value}`])!=='continue')return}await run(async()=>{const r=await api<{result:string}>(action,{path:loaded.value,host:knownHost.value,revision:revision.value,confirm:action==='knownHosts.remove'});if(action==='knownHosts.remove')accept(await api<FileResult>('files.open',{path:loaded.value}));observation.value=r.result||'没有匹配记录'})}
onUnmounted(()=>{text.value='';baseline.value='';query.value=''})
</script>
<template>
 <section class="panel files-panel" aria-labelledby="files-title">
  <div class="panel-heading"><div><span class="eyebrow">OpenSSH</span><h2 id="files-title">SSH 文件</h2></div><span class="section-note">保留原文与注释</span></div>
  <form class="file-open" @submit.prevent="open()"><label>文件绝对路径<input v-model="path" autocomplete="off" spellcheck="false" placeholder="输入当前环境的文件路径后按 Enter"></label><button type="button" class="icon-button" :disabled="busy" aria-label="选择文件" title="选择文件" @click="choose"><UiIcon name="folder" /><span class="sr-only">选择文件</span></button><button type="button" class="icon-button" :aria-expanded="history" title="历史" aria-label="历史" @click="history=!history"><UiIcon name="clock" /><span class="sr-only">历史</span></button><button class="primary" :disabled="busy||!path.trim()">打开</button></form>
  <div v-if="history" class="file-history" aria-label="文件历史"><p v-if="!config.sshFiles.length" class="muted">还没有成功打开的文件。</p><div v-for="p in config.sshFiles" :key="p"><button class="history-path" :disabled="busy" @click="open(p)">{{p}}</button><button class="icon-button" :disabled="busy" :title="`移除历史 ${p}`" :aria-label="`移除历史 ${p}`" @click="forget(p)"><UiIcon name="close" :size="15" /><span class="sr-only">移除</span></button></div></div>
  <p v-if="busy" class="muted" role="status">正在处理文件…</p><p v-if="error" class="message error" role="alert"><UiIcon name="alert" :size="15" /><span>{{error}}</span></p>
  <template v-if="loaded">
   <div class="file-meta"><UiIcon name="file" :size="15" /><span class="break">{{loaded}}</span><span v-if="readOnly" class="badge">私钥只读</span><span v-else-if="isDirty" class="badge dirty">有未保存的修改</span></div>
   <div class="file-search"><label class="search-field"><span class="sr-only">搜索文件全文</span><UiIcon name="search" :size="15" /><input v-model="query" aria-label="搜索文件全文" placeholder="搜索文件全文" autocomplete="off" spellcheck="false" @keydown.enter.prevent="locate($event.shiftKey?-1:1)"></label><output aria-live="polite">{{cursor>=0&&matches.length?`${cursor+1} / `:''}}{{matches.length}} 处匹配</output><button class="icon-button" :disabled="!matches.length" aria-label="上一个搜索结果" title="上一个搜索结果" @click="locate(-1)"><UiIcon name="up" :size="15" /><span class="sr-only">上一个</span></button><button class="icon-button" :disabled="!matches.length" aria-label="下一个搜索结果" title="下一个搜索结果" @click="locate(1)"><UiIcon name="down" :size="15" /><span class="sr-only">下一个</span></button></div>
   <label class="file-editor-label">文件内容<textarea ref="editor" v-model="text" rows="18" :readonly="readOnly" autocomplete="off" autocapitalize="off" spellcheck="false"></textarea></label>
   <div class="actions file-actions"><button class="icon-button" title="重新载入" aria-label="重新载入" :disabled="busy" @click="open(loaded)"><UiIcon name="reload" /><span class="sr-only">重新载入</span></button><button v-if="!readOnly" class="primary" title="保存文件与备份" aria-label="保存文件与备份" :disabled="busy||!isDirty" @click="save"><UiIcon name="check" :size="16" /><span>保存</span></button></div>
   <details v-if="!readOnly" class="known-host-tools" open><summary><UiIcon name="key" :size="16" /><span>主机指纹查找与删除</span><UiIcon name="chevron-down" :size="15" class="summary-chevron" /></summary><label>主机或 [主机]:端口<input v-model="knownHost" autocomplete="off"></label><div class="actions"><button :disabled="busy||!knownHost.trim()" @click="known('knownHosts.find')">查找指纹</button><button class="danger" :disabled="busy||!knownHost.trim()" @click="known('knownHosts.remove')">删除此主机记录</button></div><pre v-if="observation">{{observation}}</pre></details>
  </template>
  <p v-else class="empty compact">打开 config、known_hosts 或其他 SSH 文件。私钥仅供只读查看与搜索。</p>
  <dialog v-dialog-dismiss="()=>browser?.close()" @close="browseSequence++" ref="browser" class="file-browser" aria-labelledby="file-browser-title"><div class="dialog-heading"><div><span class="eyebrow">当前环境</span><h2 id="file-browser-title">选择文件</h2></div><button class="icon-button" type="button" title="取消" aria-label="取消" @click="browser?.close()"><UiIcon name="close" /><span class="sr-only">取消</span></button></div><form class="file-open" @submit.prevent="browse(directoryPath)"><label>目录路径<input v-model="directoryPath" autocomplete="off" spellcheck="false"></label><button class="primary">打开目录</button><button type="button" class="icon-button" title="上一级" aria-label="上一级" :disabled="!directory?.parent" @click="browse(directory!.parent!)"><UiIcon name="up" /><span class="sr-only">上一级</span></button></form><p v-if="browserError" class="message error" role="alert">{{browserError}}</p><p v-if="directory?.truncated" class="muted">此目录条目较多，仅显示前 2000 项；可直接输入文件路径。</p><div class="file-browser-list"><button v-for="entry in directory?.entries" :key="entry.path" @click="chooseEntry(entry)"><UiIcon :name="entry.directory?'folder':'file'" :size="16" /><span>{{entry.directory?'文件夹':'文件'}}</span>{{entry.name}}</button><p v-if="directory&&!directory.entries.length" class="empty compact">此目录为空。</p></div></dialog>
 </section>
</template>
